values
  ('f73c3b62-5209-4c57-8fe9-c297beeca77e', 'a3b4c5d6-7e8f-4a21-8b01-1c2d3e4f5a31', null, 'topic'::public.curated_course_node_type, 'Scientific Reasoning, Philosophical Method, and the Aims of Science', 'This opening unit asks what distinguishes scientific inquiry from other forms of disciplined reasoning. Students learn how philosophers reconstruct scientific arguments, identify assumptions, and evaluate what science is trying to achieve. Students should be able to distinguish descriptive, normative, and methodological claims about science.', 0),
  ('3b3e1fcb-3a3f-4625-b326-3054cee25d52', 'a3b4c5d6-7e8f-4a21-8b01-1c2d3e4f5a31', 'f73c3b62-5209-4c57-8fe9-c297beeca77e', 'subtopic'::public.curated_course_node_type, 'What philosophy of science studies', 'Students learn the scope of the field: not doing science directly, but examining its concepts, standards, and authority.', 0),
