  ('a193f256-6007-4a56-8eec-88cf0e0e0731', 'a3b4c5d6-7e8f-4a21-8b01-1c2d3e4f5a31', '7c2432e7-d0f8-40cd-82b3-d4fab7195a1a', 'concept'::public.curated_course_node_type, 'naturalism', null, 6),
  ('b874c494-7d39-4a75-a40b-bcb7e875a9f8', 'a3b4c5d6-7e8f-4a21-8b01-1c2d3e4f5a31', null, 'topic'::public.curated_course_node_type, 'Observation, Measurement, Experiment, and Data', 'This unit examines how observations become evidence. It treats measurement and experiment as theory-laden, instrument-mediated practices rather than simple recordings of nature. Students should be able to analyze how data are produced, cleaned, interpreted, and made evidentially relevant.', 1),
  ('de5a7bb1-634e-4017-9f69-fa16c9d80c49', 'a3b4c5d6-7e8f-4a21-8b01-1c2d3e4f5a31', 'b874c494-7d39-4a75-a40b-bcb7e875a9f8', 'subtopic'::public.curated_course_node_type, 'Observation and theory-ladenness', 'Students learn why observation depends on concepts, instruments, background theory, and trained perception.', 0),
