  ('9a08456f-3254-40a0-abfd-d2582bfa75cd', 'a3b4c5d6-7e8f-4a21-8b01-1c2d3e4f5a31', 'de5a7bb1-634e-4017-9f69-fa16c9d80c49', 'concept'::public.curated_course_node_type, 'background theory', null, 5),
