  ('8b4450c6-1a33-40cc-995e-a7d26a0ef692', 'a3b4c5d6-7e8f-4a21-8b01-1c2d3e4f5a31', '44bff052-ef57-467f-a1c8-7c55f775a7df', 'concept'::public.curated_course_node_type, 'external validity', null, 7),
  ('41a46e24-884c-48ef-9e37-a711cbaea9e0', 'a3b4c5d6-7e8f-4a21-8b01-1c2d3e4f5a31', null, 'topic'::public.curated_course_node_type, 'Confirmation, Induction, and Bayesian Reasoning', 'This topic develops the central problem of how evidence supports hypotheses. It moves from classic induction problems to contemporary probabilistic accounts of confirmation. Students should be able to explain confirmation, disconfirmation, and evidential strength in qualitative and probabilistic terms.', 2),
  ('7a2878da-a3ca-4dc7-a0b9-7cb3438699a0', 'a3b4c5d6-7e8f-4a21-8b01-1c2d3e4f5a31', '41a46e24-884c-48ef-9e37-a711cbaea9e0', 'subtopic'::public.curated_course_node_type, 'The problem of induction', 'Students examine why past regularities do not logically guarantee future cases and why this matters for scientific inference.', 0),
