  ('6e375829-417e-46d4-af0c-4016afa58107', 'a3b4c5d6-7e8f-4a21-8b01-1c2d3e4f5a31', 'c4c58b29-b984-4859-9c89-b57c66a46fd0', 'subtopic'::public.curated_course_node_type, 'Epistemic values in theory choice', 'Students learn how scientists use values that guide belief without being merely subjective preferences.', 0),
