  ('3480e66c-432a-4857-8dfd-f56936da2b05', 'a3b4c5d6-7e8f-4a21-8b01-1c2d3e4f5a31', null, 'topic'::public.curated_course_node_type, 'Philosophy of Physics and the Limits of Intuition', 'This special-science unit explores how physics pushes philosophical questions about space, time, probability, causation, explanation, and reality beyond ordinary intuition. Students should be able to connect general philosophy of science debates with physics examples without requiring advanced physics.', 13),
