  ('d808994d-f4a5-4cc3-a48d-35b7dd839e9a', 'a3b4c5d6-7e8f-4a21-8b01-1c2d3e4f5a31', 'f88a7b87-804f-430d-b63a-382d9da7356e', 'subtopic'::public.curated_course_node_type, 'Replication and reproducibility', 'Students distinguish repeating an experiment from reproducing an analysis and from generalizing a result.', 0),
