  ('e9d81c44-e41a-45d1-afff-4b16cbee2434', 'a3b4c5d6-7e8f-4a21-8b01-1c2d3e4f5a31', null, 'topic'::public.curated_course_node_type, 'Capstone: Case Study in a Special Science', 'The capstone asks students to apply the course''s conceptual toolkit to one mature case: climate science, medicine, epidemiology, economics, neuroscience, evolutionary biology, physics, or AI. Students should be able to integrate evidence, explanation, causation, modeling, values, and expertise into a sustained philosophical analysis.', 16),
  ('0af07f9c-3035-456b-996f-7a82969309c2', 'a3b4c5d6-7e8f-4a21-8b01-1c2d3e4f5a31', 'e9d81c44-e41a-45d1-afff-4b16cbee2434', 'subtopic'::public.curated_course_node_type, 'Selecting and framing the case', 'Students learn to choose a case with a clear scientific question, evidential structure, and philosophical stakes.', 0),
